#include "postquantiquecoin/mining/CpuPowEngine.h"
#include "postquantiquecoin/blockchain/Difficulty.h"
#include <chrono>
#include <iostream>
#include <thread>
namespace pqc { Result<Block> CpuPowEngine::Mine(MiningJob& job,uint32_t threads){ stopped_=false; if(threads==0) threads=1; std::atomic<bool> found{false}; std::atomic<uint64_t> hashes{0}; Block result; std::vector<std::thread> workers; for(uint32_t i=0;i<threads;++i) workers.emplace_back(&CpuPowEngine::WorkerLoop,this,std::ref(job),i,threads,std::ref(found),std::ref(result),std::ref(hashes)); for(auto& t:workers) t.join(); lastHashes_=hashes.load(); if(found) return Result<Block>::Ok(result); return Result<Block>::Err("mining stopped"); } void CpuPowEngine::Stop(){ stopped_=true; } double CpuPowEngine::GetHashrate() const { return static_cast<double>(lastHashes_.load()); } void CpuPowEngine::WorkerLoop(MiningJob& job,uint32_t idx,uint32_t threads,std::atomic<bool>& found,Block& result,std::atomic<uint64_t>& hashes){ Block b=job.candidateBlock; for(uint64_t n=idx; !stopped_ && !job.cancelled.load() && !found.load(); n+=threads){ b.header.nonce=n; auto h=b.GetHash(); ++hashes; if((n%(threads*200000ULL))==idx) PrintProgress(job,n,h,threads); if(Difficulty::CheckProofOfWork(h,b.header.bits)){ if(!found.exchange(true)) result=b; break; } } } void CpuPowEngine::PrintProgress(const MiningJob& job,uint64_t nonce,const std::string& hash,uint32_t threads) const { std::cout<<"mining height="<<job.height<<" nonce="<<nonce<<" hash="<<hash<<" bits="<<job.bits<<" threads="<<threads<<'\n'; } }
